enum Color {
	Red;
	Green;
}

typedef Opt = {var a:Int; var ?b:String;}

class Base {
	public function new() {}

	public function n():String
		return 'base';
}

class Child extends Base {
	override public function n():String
		return 'child';
}

class Main {
	static function main() {
		final xs = [1, 2, 3, 2];
		var y = 0;
		final a:Map<Int, Int> = [];
		for (x in xs) a[x] = y = x + y;
		Sys.println(Std.string([a, y]));
		final b:Map<Int, Array<Int>> = [];
		for (x in xs) b[x] = [];
		Sys.println(Std.string([b]));
		final c:Map<String, Float> = [];
		for (x in xs) c['k$x'] = x;
		Sys.println(Std.string([c]));
		final d:Map<Color, Null<Int>> = [];
		for (x in xs) d[x > 1 ? Red : Green] = null;
		Sys.println(Std.string([d]));
		final e:Map<Int, Color> = [];
		for (x in xs) e[x] = x > 1 ? Red : Green;
		Sys.println(Std.string([e]));
		final f:Map<Int, Int->Int> = [];
		for (x in xs) f[x] = v -> v + x;
		Sys.println(Std.string([f[2](1)]));
		final g:Map<Int, Opt> = [];
		for (x in xs) g[x] = {a: x};
		Sys.println(Std.string([g]));
		final h:Map<String, Base> = [];
		for (x in xs) h['$x'] = new Child();
		Sys.println(Std.string([h['1'].n()]));
		final i:Map<Int, Dynamic> = [];
		for (x in xs) i[x] = 'd$x';
		Sys.println(Std.string([i]));
		final j:Map<Int, Map<Int, Int>> = [];
		for (x in xs) j[x] = [x => 1];
		Sys.println(Std.string([j]));
		final k:Map<Int, Int> = [];
		// lead
		for (x in xs) /* mid */
			k[y = x] = x; // trail
		Sys.println(Std.string([k, y]));
		final l:Map<Int, Int> = [];
		for (x in xs) if (x > 1) for (z in 0...x) l[z] = x;
		Sys.println(Std.string([l]));
		var m:Map<Int, Int> = [];
		for (x in xs) m[x] = x;
		m = [];
		Sys.println(Std.string([m]));
		final n:Map<Int, () -> Int> = [];
		for (x in xs) n[x] = () -> n.exists(x) ? 1 : 0;
		Sys.println(Std.string([n[1]()]));
		final o:Map<Int, Bool> = [];
		for (x in xs) o[x] = x is Int;
		Sys.println(Std.string([o]));
		final p:Map<String, Int> = [];
		for (x in xs) p[(x is Int) ? 'a' : 'b'] = x;
		Sys.println(Std.string([p]));
		final q:Map<Int, Int> = [];
		for (x in xs) q[x] = x > 1 ? 1 : 2;
		Sys.println(Std.string([q]));
		final r:Map<Int, Int> = [];
		for (x in xs) r[x] = cast x;
		Sys.println(Std.string([r]));
		final s:Map<Int, Int> = [];
		for (x in xs) s[untyped x] = x;
		Sys.println(Std.string([s]));
		final t:Map<Int, Null<Int>> = [];
		for (x in xs) t[x] = a[x] ?? 0;
		Sys.println(Std.string([t]));
		final u:Map<Int, Int> = [];
