class Main {
	static function rw(n:Int, o:Null<{col:Int, f:Bool}>):Int return n + (o == null ? 0 : o.col);

	static function fits(n:Int, d:Int):Bool return n > d;

	static function repro(c:Bool, col:Int, w:Int):Int {
		var r = 0;
		inline function rf(x:Int, z:Bool):Int return rw(x, {col: x, f: z});
		if (c || fits(w - rf(col, true), 1)) r = 1;
		return r;
	}

	static function lambdaBody(c:Bool, w:Int):Int {
		var r = 0;
		inline function rf(x:Int, z:Bool):Int return rw(x, {col: x, f: z});
		if (c || [1].filter(v -> fits(w - rf(v, true), 1)).length > 0) r = 1;
		return r;
	}

	static function nullCoalesce(c:Null<Int>, col:Int, w:Int):Int {
		var r = 0;
		inline function rf(x:Int, z:Bool):Int return rw(x, {col: x, f: z});
		if ((c ?? (w - rf(col, true))) > 1) r = 1;
		return r;
	}

	static function main() {
		Sys.println([repro(false, 3, 80), lambdaBody(false, 80), nullCoalesce(null, 3, 80)].join(','));
	}
}

