class C {

	public static function run(parts:Array<String>, items:Array<String>, cb:Int->Void):Void {
		if (items.length == 0) {
			cb(0);
			return;
		}
		if (parts.length == 0) {
			go(items, cb);
			return;
		} else if (parts.length == 1) {
			if (parts[0] != '')
				go([for (a in items) parts[0] + '/' + a], cb);
			else
				go(items, cb);
			return;
		}
		cb(parts.length);
	}

	public static function go(items:Array<String>, cb:Int->Void):Void {
		cb(items.length);
	}

}

